<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/private/FamilyStore.php';
// Run only against an isolated, disposable CI/test database, never a family database.
if (getenv('OSMON_TEST_DATABASE')!=='osmon_test') { fwrite(STDERR,"Dedicated osmon_test database required.\n");exit(1); }
$config=['host'=>getenv('OSMON_TEST_HOST')?:'127.0.0.1','port'=>(int)(getenv('OSMON_TEST_PORT')?:3306),'database'=>'osmon_test','username'=>getenv('OSMON_TEST_USER')?:'root','password'=>getenv('OSMON_TEST_PASSWORD')?:'test-only'];
$db=connectFamily($config);
foreach(explode(';',file_get_contents(dirname(__DIR__).'/private/schema.sql')) as $sql) if(trim($sql)!=='') $db->exec($sql);
$now=1000000.0;$s=new FamilyStore($db,static function()use(&$now){return $now;});
function eq(mixed $a,mixed $b):void { if($a!==$b) throw new RuntimeException('Assertion failed: '.var_export([$a,$b],true)); }
function rejected(int $code,Closure $fn):void { try{$fn();}catch(FamilyAPIError $e){eq($e->status,$code);return;}throw new RuntimeException('Expected error '.$code); }
function callAPI(string $m,string $path,string $token='',array $body=[]):array { global $s;return $s->dispatch($m,$path,$token,$body); }
function fixture():array {
 global $db,$now;$now=1000000.0;
 $db->exec('DELETE FROM osmon_parents');$db->exec('DELETE FROM osmon_devices');$db->exec('DELETE FROM osmon_rates');
 $p=callAPI('POST','/v1/parents')['token'];$other=callAPI('POST','/v1/parents')['token'];
 $pair=callAPI('POST','/v1/pairings','',['name'=>'Testgerät','config'=>['limit'=>2,'tasks'=>[]]]);
 return [$p,$other,$pair];
}
function paired():array { [$p,$o,$pair]=fixture();callAPI('POST','/v1/claims',$p,['code'=>$pair['code']]);$d=callAPI('GET','/v1/device',$pair['token']);return [$p,$o,$pair,$d]; }
function fix():array {global $now;return ['latitude'=>53.86,'longitude'=>10.68,'accuracy'=>100,'measured'=>$now];}
$tests=[];
$tests['pairing one use']=function(){[$p,$o,$pair]=fixture();eq(callAPI('GET','/v1/device',$pair['token'])['paired'],false);rejected(409,fn()=>callAPI('POST','/v1/device/ack',$pair['token'],['version'=>1,'completed'=>[],'day'=>1]));callAPI('POST','/v1/claims',$p,['code'=>$pair['code']]);rejected(404,fn()=>callAPI('POST','/v1/claims',$o,['code'=>$pair['code']]));};
$tests['pair expiry']=function(){global $now;[$p,$o,$pair]=fixture();$now+=601;rejected(404,fn()=>callAPI('POST','/v1/claims',$p,['code'=>$pair['code']]));rejected(401,fn()=>callAPI('GET','/v1/device',$pair['token']));};
$tests['tenant isolation']=function(){[$p,$o,$pair,$d]=paired();eq(callAPI('GET','/v1/children',$o)['children'],[]);rejected(404,fn()=>callAPI('DELETE','/v1/children/'.$d['id'],$o));rejected(401,fn()=>callAPI('GET','/v1/children',$pair['token']));};
$tests['config version and status']=function(){[$p,$o,$pair,$d]=paired();$id=newUUID();$body=['version'=>1,'config'=>['limit'=>0,'tasks'=>[['id'=>$id,'title'=>'Zähne putzen','repeat'=>'daily']]]];callAPI('PUT','/v1/children/'.$d['id'].'/config',$p,$body);rejected(409,fn()=>callAPI('PUT','/v1/children/'.$d['id'].'/config',$p,$body));rejected(409,fn()=>callAPI('POST','/v1/device/ack',$pair['token'],['version'=>1,'completed'=>[],'day'=>1]));callAPI('POST','/v1/device/ack',$pair['token'],['version'=>2,'completed'=>[$id],'day'=>1]);$r=callAPI('GET','/v1/children',$p)['children'][0];eq([$r['version'],$r['applied'],$r['completed'],$r['config']['limit']],[2,2,[$id],0]);};
$tests['config validation']=function(){[$p,$o,$pair,$d]=paired();foreach([['limit'=>true,'tasks'=>[]],['limit'=>4,'tasks'=>[]],['limit'=>2,'tasks'=>[[]]],['limit'=>2,'tasks'=>[],'extra'=>1]] as $c)rejected(400,fn()=>callAPI('PUT','/v1/children/'.$d['id'].'/config',$p,['version'=>1,'config'=>$c]));};
$tests['ack rejects foreign task']=function(){[$p,$o,$pair]=paired();rejected(400,fn()=>callAPI('POST','/v1/device/ack',$pair['token'],['version'=>1,'completed'=>['foreign'],'day'=>1]));};
$tests['device revoke']=function(){[$p,$o,$pair,$d]=paired();callAPI('DELETE','/v1/children/'.$d['id'],$p);rejected(401,fn()=>callAPI('GET','/v1/device',$pair['token']));};
$tests['parent deletion cascades']=function(){global $db;[$p,$o,$pair]=paired();$code=callAPI('POST','/v1/web-codes',$p)['code'];$web=callAPI('POST','/v1/web-codes/redeem','',['code'=>$code])['token'];callAPI('DELETE','/v1/parents',$p);rejected(401,fn()=>callAPI('GET','/v1/children',$web));rejected(401,fn()=>callAPI('GET','/v1/device',$pair['token']));eq((int)$db->query('SELECT count(*) FROM osmon_devices')->fetchColumn(),0);};
$tests['parent expiry persists cleanup on rejected auth']=function(){global $now,$db;[$p,$o,$pair]=paired();$now+=91*86400;rejected(401,fn()=>callAPI('GET','/v1/device',$pair['token']));eq((int)$db->query('SELECT count(*) FROM osmon_devices')->fetchColumn(),0);};
$tests['hashed credentials']=function(){global $db;[$p,$o,$pair]=fixture();$dump=encodeJSON([$db->query('SELECT * FROM osmon_parents')->fetchAll(),$db->query('SELECT * FROM osmon_devices')->fetchAll()]);foreach([$p,$o,$pair['token'],$pair['code']] as $raw)eq(str_contains($dump,$raw),false);eq(str_contains($dump,tokenHash($pair['token'])),true);};
$tests['browser same scope and one use']=function(){[$p,$o,$pair]=paired();$code=callAPI('POST','/v1/web-codes',$p)['code'];$web=callAPI('POST','/v1/web-codes/redeem','',['code'=>$code])['token'];eq(callAPI('GET','/v1/children',$web),callAPI('GET','/v1/children',$p));rejected(404,fn()=>callAPI('POST','/v1/web-codes/redeem','',['code'=>$code]));callAPI('DELETE','/v1/browser-session',$web);rejected(401,fn()=>callAPI('GET','/v1/children',$web));eq(count(callAPI('GET','/v1/children',$p)['children']),1);};
$tests['web code expiry']=function(){global $now;[$p]=fixture();$code=callAPI('POST','/v1/web-codes',$p)['code'];$now+=301;rejected(404,fn()=>callAPI('POST','/v1/web-codes/redeem','',['code'=>$code]));};
$tests['browser session expiry']=function(){global $now;fixture();$web=callAPI('POST','/v1/browser-access')['token'];$now+=7*86400+1;rejected(401,fn()=>callAPI('GET','/v1/children',$web));};
$tests['unpaired location rejected']=function(){[$p,$o,$pair]=fixture();rejected(409,fn()=>callAPI('POST','/v1/device/location',$pair['token'],fix()));};
$tests['location validation']=function(){[$p,$o,$pair]=paired();foreach([['latitude'=>true],['longitude'=>181],['accuracy'=>-1],['measured'=>1],['extra'=>1]]as $v)rejected(400,fn()=>callAPI('POST','/v1/device/location',$pair['token'],array_replace(fix(),$v)));};
$tests['location replace delete expiry']=function(){global $now,$db;[$p,$o,$pair]=paired();callAPI('POST','/v1/device/location',$pair['token'],fix());callAPI('POST','/v1/device/location',$pair['token'],array_replace(fix(),['latitude'=>54]));eq(callAPI('GET','/v1/device',$pair['token'])['location']['latitude'],54);callAPI('DELETE','/v1/device/location',$pair['token']);eq(callAPI('GET','/v1/device',$pair['token'])['location'],null);callAPI('POST','/v1/device/location',$pair['token'],fix());$now+=86401;eq(callAPI('GET','/v1/device',$pair['token'])['location'],null);eq($db->query('SELECT location FROM osmon_devices')->fetchColumn(),null);};
$tests['only child enables consent']=function(){[$p,$o,$pair,$d]=paired();rejected(409,fn()=>callAPI('POST','/v1/children/'.$d['id'].'/location-request',$p));rejected(401,fn()=>callAPI('PUT','/v1/device/location-sharing',$p,['enabled'=>true]));callAPI('PUT','/v1/device/location-sharing',$pair['token'],['enabled'=>true]);rejected(404,fn()=>callAPI('POST','/v1/children/'.$d['id'].'/location-request',$o));};
function requested():array{[$p,$o,$pair,$d]=paired();callAPI('PUT','/v1/device/location-sharing',$pair['token'],['enabled'=>true]);$r=callAPI('POST','/v1/children/'.$d['id'].'/location-request',$p)['request'];return [$p,$o,$pair,$d,$r];}
$tests['request dedupe and matching fresh fix']=function(){[$p,$o,$pair,$d,$r]=requested();eq(callAPI('POST','/v1/children/'.$d['id'].'/location-request',$p)['request']['id'],$r['id']);rejected(409,fn()=>callAPI('POST','/v1/device/location',$pair['token'],array_merge(fix(),['requestId'=>'wrong'])));rejected(400,fn()=>callAPI('POST','/v1/device/location',$pair['token'],array_merge(fix(),['requestId'=>$r['id'],'measured'=>$r['created']-6])));callAPI('POST','/v1/device/location',$pair['token'],array_merge(fix(),['requestId'=>$r['id']]));eq(callAPI('GET','/v1/device',$pair['token'])['locationRequest']['state'],'received');rejected(409,fn()=>callAPI('POST','/v1/device/location',$pair['token'],array_merge(fix(),['requestId'=>$r['id']])));};
$tests['late reply cannot satisfy newer request']=function(){global $now;[$p,$o,$pair,$d,$r]=requested();$now+=91;eq(callAPI('GET','/v1/device',$pair['token'])['locationRequest']['state'],'expired');$new=callAPI('POST','/v1/children/'.$d['id'].'/location-request',$p)['request'];eq($new['id']!==$r['id'],true);rejected(409,fn()=>callAPI('POST','/v1/device/location',$pair['token'],array_merge(fix(),['requestId'=>$r['id']])));};
$tests['consent revoke clears position and request']=function(){[$p,$o,$pair,$d,$r]=requested();callAPI('POST','/v1/device/location',$pair['token'],fix());callAPI('PUT','/v1/device/location-sharing',$pair['token'],['enabled'=>false]);$v=callAPI('GET','/v1/device',$pair['token']);eq([$v['location'],$v['locationRequest'],$v['locationSharing']],[null,null,false]);rejected(409,fn()=>callAPI('POST','/v1/device/location',$pair['token'],array_merge(fix(),['requestId'=>$r['id']])));};
$tests['failure keeps older fix distinct']=function(){[$p,$o,$pair,$d,$r]=requested();callAPI('POST','/v1/device/location',$pair['token'],fix());callAPI('POST','/v1/device/location-result',$pair['token'],['requestId'=>$r['id'],'state'=>'permissionDenied']);$v=callAPI('GET','/v1/device',$pair['token']);eq($v['locationRequest']['state'],'permissionDenied');eq($v['location']!==null,true);rejected(429,fn()=>callAPI('POST','/v1/children/'.$d['id'].'/location-request',$p));};
$tests['ten device limit']=function(){[$p]=fixture();for($i=0;$i<11;$i++){$pair=callAPI('POST','/v1/pairings','',['name'=>'Device '.$i,'config'=>['limit'=>2,'tasks'=>[]]]);if($i<10)callAPI('POST','/v1/claims',$p,['code'=>$pair['code']]);else rejected(400,fn()=>callAPI('POST','/v1/claims',$p,['code'=>$pair['code']]));}};
$tests['rate limits persist without raw IP']=function(){global $s,$db,$now;fixture();for($i=0;$i<10;$i++)$s->rate('192.0.2.1','/v1/claims',str_repeat('a',64));rejected(429,fn()=>$s->rate('192.0.2.1','/v1/claims',str_repeat('a',64)));eq(str_contains(encodeJSON($db->query('SELECT * FROM osmon_rates')->fetchAll()),'192.0.2.1'),false);$now+=61;$s->rate('192.0.2.1','/v1/claims',str_repeat('a',64));};
$failed=0;foreach($tests as $name=>$test){try{$test();echo "PASS $name\n";}catch(Throwable $e){$failed++;fwrite(STDERR,"FAIL $name: ".$e->getMessage()."\n");}}
echo count($tests)." tests, $failed failures\n";exit($failed?1:0);
